<script>
import { api } from '@/http'
import sortAndFilter from '@/composables/router_aware_sort_and_filter'
import MemberPreview from '@/components/groups/MemberPreview.vue'
import CoiDetail from '@/components/applications/CoiDetail.vue'
import configs from '@/configs.json'
import { useStore } from 'vuex'
import { useScopeOfWorkMemberRows, memberRetirementTransition } from '@/composables/scope_of_work_member_rows'
import ScopeOfWorkMemberRoles from './ScopeOfWorkMemberRoles.vue'
import ScopeOfWorkMemberDiscard from './ScopeOfWorkMemberDiscard.vue'
// import GroupMembersFilter from '@/components/groups/GroupMembersFilter.vue'

export default {
    name: 'MemberList',
    components: {
        MemberPreview,
        CoiDetail,
        ScopeOfWorkMemberRoles,
        ScopeOfWorkMemberDiscard,
        // GroupMembersFilter
    },
    props: {
      scopeComparison: { type: Object, default: null },
      readonly: {
        type: Boolean,
        default: false
      }
    },
    emits: ['updated'],
    setup(props) {
        const store = useStore();
        const { rows: memberRows, canUseLiveMember } = useScopeOfWorkMemberRows(
            () => store.getters['groups/currentItemOrNew']?.members,
            () => props.scopeComparison,
            () => store.getters['groups/currentItemOrNew']?.uuid,
        );
        const {sort, filter} = sortAndFilter({field: 'person.last_name', desc: false});

        return {
            sort,
            filter,
            memberRows,
            canUseLiveMember,
            memberRetirementTransition,
        }
    },
    data() {
        return {
            showFilter: false,
            showConfirmRetire: false,
            showConfirmUnretire: false,
            showConfirmRemove: false,
            filters: {
                keyword: null,
                roleId: null,
                needsCoi: null,
                needsTraining: null,
                hideAlumns: true
            },
            tableFields: [
                {
                    name: 'id',
                    label: '',
                    type: Number,
                    sortable: false,
                },
                {
                    name: 'person.first_name',
                    label: 'First',
                    type: String,
                    sortable: true,
                },
                {
                    name: 'person.last_name',
                    label: 'Last',
                    type: String,
                    sortable: true,
                },
                {
                    name: 'person.timezone',
                    label: 'Closest City (for timezone)',
                    type: String,
                    sortable: true,
                },
                {
                    name: 'roles',
                    label: 'Roles',
                    sortable: true,
                    sortFunction (a,  b) {
                        const aComp = a.roles.map(r => r.display_name ?? r.label).join(',');
                        const bComp = b.roles.map(r => r.display_name ?? r.label).join(',');

                        if (aComp === bComp) {
                            return 0;
                        }

                        return (aComp > bComp) ? 1 : -1;
                    }
                },
                {
                    name: 'coi_last_completed',
                    label: 'COI Completed',
                    type: Date,
                    sortable: true,
                },
                {
                    name: 'requirements',
                    label: 'Reqs',
                    type: String,
                    sortable: false
                },
                {
                    name: 'actions',
                    label: '',
                    type: Object,
                    sortable: false
                }

            ],
            selectedMember: null,
            members: [],
            showCoiDetail: false,
            coi: null,
            // showCoiReport: false
        }
    },
    computed: {
        roles () {
            return configs.groups.roles;
        },

        group () {
            return this.$store.getters['groups/currentItemOrNew'];
        },

        filteredMembers () {
            return this.memberRows
                    .filter(m => this.matchesFilters(m))
                    .filter(m => {
                        if (this.filters.hideAlumns) {
                            if (['added', 'removed', 'changed'].includes(m.comparison?.operation)) return true;
                            return m.snapshotOnly ? !m.isRetired : m.end_date === null;
                        }
                        return m;
                    });
        },
        operationalMembers () {
            return this.filteredMembers.filter(row => this.canUseLiveMember(row)).map(row => row.member);
        },
        showOperationalLinks () {
            return this.operationalMembers.length > 0 || !this.memberRows.some(row => row.snapshotOnly);
        },
        filteredEmails () {
            return this.operationalMembers.map(m => `${m.person.name} <${m.person.email}>`)
        },
        fieldsForGroupType () {
            const fields = [...this.tableFields];
            if (!this.group.has_coi_requirement) {
                fields.splice(fields.findIndex(f => f.name === 'coi_last_completed'), 1);
            }
            return fields;
        },
        coiCuttoff () {
            const cuttoff = new Date();
            cuttoff.setFullYear(cuttoff.getFullYear()-1);
            return cuttoff;
        },
        selectedMemberName () {
            return this.selectedMember?.member?.person?.name ?? this.selectedMember?.member?.label ?? null
        },
        showCoordinatorActions () {
            return this.hasAnyMemberPermission(['groups-manage', ['info-edit', this.group]])
        },
        showAddMemberButton () {
            return this.hasAnyPermission([['members-invite', this.group], 'groups-manage', 'ep-applications-manage', 'annual-updates-manage']) && !this.readonly
        },
        showMemberReportButton () {
            return this.hasAnyPermission([['members-invite', this.group], 'groups-manage', 'ep-applications-manage', 'annual-updates-manage'])
        },
        exportUrl () {
            const query = `?member_ids=${this.operationalMembers.map(m => m.id).join(',')}`;
            return `/api/report/groups/${this.group.uuid}/member-export${query}`;
        },
        features () {
          return this.$store.state.systemInfo.app.features
        },
        canAdminCompleteCoi () {
          return Boolean(this.$store.state.systemInfo.env == 'local' || this.$store.state.systemInfo.env == 'demo') && (this.hasRole('super-admin') || this.hasRole('super-user')) && ! this.readonly
        },
    },
    watch: {
      group: {
        immediate: true,
        handler (to, from) {
          if (!to.id) { return; }
          this.$store.dispatch('groups/getMembers', { group: this.group, force: true});
        }
      }
    },
    methods: {
        toggleFilter() {
            this.showFilter = !this.showFilter;
        },
        canMutate(row) {
          return !this.readonly && this.canUseLiveMember(row);
        },
        matchesFilters(row) {
          const member = row.member;
          if (row.snapshotOnly) {
            if (this.filters.keyword) {
              const pattern = new RegExp(this.filters.keyword, 'i');
              if (![member.first_name, member.last_name, member.label, member.email, member.notes]
                  .some(value => value && pattern.test(value))) return false;
            }
            const selectedRole = Object.values(this.roles).find(role => String(role.id) === String(this.filters.roleId));
            if (this.filters.roleId && !member.roles?.some(role => String(role.id) === String(this.filters.roleId)
                || (selectedRole && role.name === selectedRole.name))) return false;
            // Missing historical requirements are unknown, not failed requirements.
            if (this.filters.needsCoi || this.filters.needsTraining) return false;
            return true;
          }
          if (this.filters.keyword && !member.matchesKeyword(this.filters.keyword)) {
            return false;
          }
          if (this.filters.roleId && !member.hasRole(this.filters.roleId)) {
            return false;
          }
          if (this.filters.needsCoi && member.coiUpToDate()) {
            return false;
          }

          if (this.filters.needsTraining && member.trainingComplete()) {
            return false;
          }

          return true;
        },
        toggleItemDetails(item) {
          item.showDetails = !item.showDetails;
        },
        editMember (member) {
          if (!this.canMutate(member)) return;
          this.$router.push(this.append(this.$route.path, `members/${member.member.id}`))
        },

        // Retire member
        confirmRetireMember (member) {
          if (!this.canMutate(member)) return;
          this.showConfirmRetire = true;
          this.selectedMember = member;
        },
        async retireMember () {
          if (!this.canMutate(this.selectedMember)) return;
          try {
            await this.$store.dispatch('groups/memberRetire', {
              uuid: this.group.uuid,
              memberId: this.selectedMember.member.id,
              startDate: this.selectedMember.member.start_date,
              endDate: new Date().toISOString()
            });
            this.cancelRetire();
            this.$emit('updated');
          } catch (error) {
              console.error(error);
          }
        },
        cancelRetire () {
          this.selectedMember = null;
          this.showConfirmRetire = false;
        },

        // Unretire Member
        // confirmUnretireMember (member) {
        //     console.log('confirmUnretireMember');
        //     // this.showConfirmUnretire = true;
        //     // this.selectedMember = member;
        // },
        async unretireMember () {
          if (!this.canMutate(this.selectedMember)) return;
          try {
            await this.$store.dispatch('groups/memberUnretire', {
              uuid: this.group.uuid,
              memberId: this.selectedMember.member.id,
            });
            this.cancelUnretire();
            this.$emit('updated');
          } catch (error) {
            console.error(error);
          }
        },
        cancelUnretire () {
          this.selectedMember = null;
          this.showConfirmUnretire = false;
        },


        // Remove Member
        confirmRemoveMember (member) {
          if (!this.canMutate(member)) return;
          this.showConfirmRemove = true;
          this.selectedMember = member;
        },
        async removeMember () {
          if (!this.canMutate(this.selectedMember)) return;
          try {
            await this.$store.dispatch('groups/memberRemove', {
              uuid: this.group.uuid,
              memberId: this.selectedMember.member.id,
              startDate: this.selectedMember.member.start_date,
              endDate: new Date().toISOString()
            });
            this.cancelRemove();
            this.$emit('updated');
          } catch (error) {
            console.error(error);
          }
        },
        cancelRemove () {
          this.selectedMember = null;
          this.showConfirmRemove = false;
        },


        goToMember (member) {
            if (!this.canUseLiveMember(member)) return;
            this.$router.push({name: 'PersonDetail', params: {uuid: member.member.person.uuid}})
        },
        hasAnyMemberPermission () {
            const hasPerm = this.hasAnyPermission([
                ['members-update', this.group],
                ['members-retire', this.group],
                ['members-remove', this.group],
                'groups-manage'
            ])

            return hasPerm;
        },
        getCoiDateStyle (member) {
            if (member.coi_last_completed === null) {
                return 'text-red-700';
            }
            return 'text-yellow-500';
        },
        async viewCoi (coiId) {
            this.showCoiDetail = true;
            this.coi = await api.get(`/api/cois/${coiId}`).then(response => response.data);
        },
        downloadCoiReport() {
            const reportUrl = `/api/report/${this.group.coi_code}`
            window.location = reportUrl;
        },
        confirmUnretire (member) {
            if (!this.canMutate(member)) return;
            this.showConfirmUnretire = true;
            this.selectedMember = member;
        },
        requirementsMet (member) {
            if (this.group.has_coi_requirement && member.needsCoi) {
                return false;
            }

            if (this.group.isEp() && !member.hasAnyExpertise) {
                return false;
            }
            if (!this.cocRequirementMet(member)) { return false; }
            return true;
        },
        getRequirements (member) {
            const requirements = {}
            if (this.group.has_coi_requirement) {
                requirements.coi = {
                    label: 'COI is up to date',
                    met: !member.needsCoi,
                }
            }
            if (this.group.isEp()) {
                requirements.expertise = {
                    label: 'Expertise provided',
                    met: member.hasAnyExpertise,
                };
            }
            requirements.coc = {
              label: 'Code of Conduct is current',
              met: this.cocRequirementMet(member),
            };

            return requirements
        },
        cocStatus(member) {
          return member.person.coc?.status ?? 'missing';
        },
        cocIsCurrent(member) {
          return this.cocStatus(member) === 'current';
        },
        cocRequirementMet(member) {
          const cocStatus = this.cocStatus(member);
          return cocStatus === 'current' || cocStatus === 'expiring_soon';
        },
        async adminCompleteCoi (row) {
        if (!this.canMutate(row) || !this.canAdminCompleteCoi) return;
        const member = row.member;
        try {
          await api.post(`/api/coi/${this.group.coi_code}`, {
            group_member_id: member.id,
            work_fee_lab: 0,
            contributions_to_gd_in_group: 2,
            coi: 0,
            coi_attestation: 1,
            data_policy_attestation: 1,
            admin_override: 1,
          });
          await this.$store.dispatch('groups/getMembers', { group: this.group, force: true });
        } catch (e) {
          console.error(e);
          const apiMsg =
            e?.response?.data?.message ||
            (typeof e?.response?.data === 'string' ? e.response.data : null);

          const memberName = member?.person?.name || `${member?.person?.first_name ?? ''} ${member?.person?.last_name ?? ''}`.trim() || 'this member';

          this.$store.commit(
            'pushError',
            apiMsg
              ? `Could not complete COI for ${memberName}: ${apiMsg}`
              : `Could not complete COI for ${memberName}. Please try again.`
          );
        }
      },
    }
}
</script>
<template>
  <div>
    <div class="flex justify-between items-end">
      <div class="flex space-x-2 items-center">
        <h2>Members</h2>
        <button
          v-if="memberRows.length > 0"
          class="px-3 py-2 rounded-t transition-color"
          :class="{'rounded-b': !showFilter, 'bg-blue-200': showFilter}"
          @click="toggleFilter"
        >
          <icon-filter width="16" height="16" />
        </button>
      </div>
      <div class="flex space-x-2 items-center pb-0.5">
        <div v-if="showAddMemberButton">
          <popper content="Add a member" hover arrow>
            <router-link
              class="btn btn-icon"
              :to="append($route.path, 'members/add')"
            >
              <icon-add class="inline-block" />
            </router-link>
          </popper>
        </div>

        <div v-if="showCoordinatorActions" class="flex space-x-2 items-center">
          <popper v-if="showOperationalLinks" :content="`Email ${operationalMembers.length} listed members`" hover arrow>
            <a
              :href="`mailto:${filteredEmails.join(', ')}`"
              class="btn btn-icon"
            >
              <icon-envelope class="inline-block" width="16" height="16" />
            </a>
          </popper>

          <dropdown-menu hide-cheveron orientation="right">
            <template #label>
              <button class="btn btn-icon">
                <icon-download width="16" height="16" />
              </button>
            </template>
            <dropdown-item class="text-right font-bold">
              Downloads:
            </dropdown-item>
            <dropdown-item class="text-right">
              <a :href="`/api/report/groups/${group.uuid}/coi-report`">COI Report</a>
              <note class="inline">
                (PDF)
              </note>
            </dropdown-item>
            <dropdown-item v-if="showMemberReportButton && showOperationalLinks" class="text-right">
              <popper class="text-center text-sm p-1" :content="`Export will include ${operationalMembers.length} members currently listed.`" hover arrow>
                <a :href="exportUrl">Member Export</a>
                <note class="inline">
                  (CSV)
                </note>
              </popper>
            </dropdown-item>
          </dropdown-menu>

          <div v-if="group.isEp() && showCoordinatorActions" />
        </div>
      </div>
    </div>
    <transition name="slide-fade-down">
      <div v-show="showFilter" class="flex justify-between px-2 space-x-2 bg-blue-200 rounded-lg">
        <div class="flex-1">
          <input-row v-model="filters.keyword" label="Keyword" type="text" label-width-class="w-20" />
          <input-row label="Role" label-width-class="w-20">
            <select v-model="filters.roleId">
              <option :value="null">
                Select&hellip;
              </option>
              <option
                v-for="role in roles"
                :key="role.id"
                :value="role.id"
              >
                {{ role.display_name }}
              </option>
            </select>
          </input-row>
        </div>
        <div class="flex-1 py-2">
          <checkbox v-model="filters.needsCoi" class="block" label="Needs COI" />
          <!-- <checkbox class="block" label="Needs Training" v-model="filters.needsTraining" /> -->
        </div>
        <div class="flex-1 py-2">
          <checkbox v-model="filters.hideAlumns" class="block" label="Hide Retired/Alumni" />
        </div>
      </div>
    </transition>
    <div class="mt-3 py-2 w-full overflow-x-auto">
      <data-table
        v-if="memberRows.length > 0"
        v-model:sort="sort"
        :fields="fieldsForGroupType"
        :data="filteredMembers"
        :detail-rows="true"
        :row-class="(item) => `${canUseLiveMember(item) ? 'cursor-pointer' : ''}${ item.isRetired ? ' retired-member' : ''}`"
        @row-click="goToMember"
      >
        <template #cell-id="{item}">
          <button class="w-9 align-center block -mx-3" @click.stop="toggleItemDetails(item)">
            <icon-cheveron-right v-if="!item.showDetails" class="m-auto cursor-pointer" />
            <icon-cheveron-down v-if="item.showDetails" class="m-auto cursor-pointer" />
          </button>
        </template>
        <template #cell-person_first_name="{item, value}">
          <del v-if="item.comparison?.operation === 'removed'" class="text-red-700">{{ value }}</del>
          <span v-else>{{ value }}</span>
        </template>
        <template #cell-person_last_name="{item, value}">
          <del v-if="item.comparison?.operation === 'removed'" class="text-red-700">{{ value }}</del>
          <span v-else>{{ value }}</span>
          <span v-if="item.comparison?.operation === 'added'" class="ml-1 rounded bg-green-50 px-1 text-xs text-green-800">Added</span>
          <span v-if="item.comparison?.operation === 'removed'" class="ml-1 rounded bg-red-50 px-1 text-xs text-red-700">Removed</span>
          <ScopeOfWorkMemberDiscard v-if="scopeComparison && ['added', 'removed'].includes(item.comparison?.operation)"
            :person-id="item.member.person_id" :operation="item.comparison.operation" :member-label="item.comparison.label" />
          <small v-if="memberRetirementTransition(item.comparison)" class="block text-gray-700">
            {{ memberRetirementTransition(item.comparison) }}
            <ScopeOfWorkMemberDiscard v-if="scopeComparison" :person-id="item.member.person_id" kind="retirement"
              :operation="item.comparison.field_changes.find(change => change.field === 'end_date').before === null ? 'retire' : 'unretire'"
              :member-label="item.comparison.label" />
          </small>
        </template>
        <template #cell-roles="{item}">
          <ScopeOfWorkMemberRoles :roles="item.roles" :comparison="item.comparison" :snapshot-only="item.snapshotOnly"
            :allow-discard="!!scopeComparison" :person-id="item.member.person_id" :member-label="item.comparison?.label" />
        </template>
        <template #cell-coi_last_completed="{item}">
          <span v-if="item.snapshotOnly">—</span>
          <div v-else class="flex space-x-2">
            <span v-if="item.coi_last_completed">{{ formatDate(item.coi_last_completed) }}</span>
            <button v-if="item.member.latest_coi_id" class="link cursor-pointer" @click.stop="viewCoi(item.member.latest_coi_id)">
              <icon-view />
            </button>
            <icon-exclamation
              v-if="item.coi_last_completed === null || (item.coi_last_completed < yearAgo())"
              :class="getCoiDateStyle(item)"
            />
          </div>
        </template>

        <template #cell-actions="{item}">
          <button v-if="canMutate(item) && group.has_coi_requirement && item.member.needsCoi && canAdminCompleteCoi" class="btn btn-xs" @click.stop="adminCompleteCoi(item)">Complete COI</button>
          <div class="flex space-x-2 items-center">
            <dropdown-menu
              v-if="hasAnyMemberPermission() && canMutate(item)"
              :hide-cheveron="true"
              class="relative block"
            >
              <template #label>
                <button class="btn btn-xs">
                  &hellip;
                </button>
              </template>
              <dropdown-item
                v-if="hasAnyPermission([['members-update', group], 'groups-manage'])"
              >
                <div @click="editMember(item)">
                  Update membership
                </div>
              </dropdown-item>
              <dropdown-item
                v-show="!item.isRetired && hasAnyPermission([['members-retire', group], 'groups-manage'])"
              >
                <div @click="confirmRetireMember(item)">
                  Retire from group
                </div>
              </dropdown-item>
              <dropdown-item
                v-show="item.isRetired && hasAnyPermission([['members-remove', group], 'groups-manage'])"
              >
                <div @click="confirmUnretire(item)">
                  Unretire from group
                </div>
              </dropdown-item>
              <dropdown-item>
                <div @click="confirmRemoveMember(item)">
                  Remove from group
                </div>
              </dropdown-item>
            </dropdown-menu>
            <div>
              <popover hover arrow content="Receives notifications about this group." placement="top">
                <icon-notification v-if="canUseLiveMember(item) && item.member.is_contact" :width="12" :height="12" icon-name="Is a group contact" @click.stop="" />
              </popover>
            </div>
          </div>
        </template>

        <template #cell-requirements="{item}">
          <span v-if="item.snapshotOnly">—</span>
          <popover v-else hover arrow placement="top">
            <icon-checkmark v-if="requirementsMet(item.member)" :width="12" :height="12" class="text-green-600" />
            <icon-exclamation v-else :width="12" :height="12" class="text-red-700" />

            <template #content>
              <ul>
                <li v-for="req, k in getRequirements(item.member)" :key="k">
                  <icon-checkmark v-if="req.met" :width="12" :height="12" class="inline-block text-green-600" />
                  <icon-exclamation v-else :width="12" :height="12" class="inline-block text-red-700" />
                  {{ req.label }}
                </li>
              </ul>
            </template>
          </popover>
        </template>

        <template #detail="{item}">
          <MemberPreview :member="item.member" :group="group" :comparison="item.comparison" :snapshot-only="item.snapshotOnly" />
        </template>
      </data-table>
      <div v-else class="well">
        This group does not yet have any members.
      </div>
    </div>
    <teleport to="body">
      <modal-dialog v-model="showConfirmRetire" size="xs" :title="`Retire ${selectedMemberName}?`">
        <p class="text-lg">
          Are you sure you want to retire {{ selectedMemberName }} from this group?
        </p>
        <button-row submit-text="Retire Member" @submit="retireMember" @cancel="cancelRetire" />
      </modal-dialog>
      <modal-dialog v-model="showConfirmUnretire" size="xs" :title="`Retire ${selectedMemberName}?`">
        <p class="text-lg">
          Are you sure you want to un-retire {{ selectedMemberName }}?
        </p>
        <button-row submit-text="Un-retire Member" @submit="unretireMember" @cancel="cancelUnretire" />
      </modal-dialog>
      <modal-dialog v-model="showConfirmRemove" size="xs" :title="`Remove ${selectedMemberName}?`">
        <p class="text-lg">
          Are you sure you want to remove {{ selectedMemberName }} from this group?
        </p>
        <p><strong>This cannot be undone.</strong></p>
        <button-row submit-text="Remove Member" @submit="removeMember" @cancel="cancelRemove" />
      </modal-dialog>
      <modal-dialog v-model="showCoiDetail" size="xl">
        <CoiDetail v-if="coi" :coi="coi" :group="group" />
      </modal-dialog>
    </teleport>
  </div>
</template>
<style>
.inset {
  box-shadow:
    inset 0px 11px 15px -10px #CCC,
    inset 0px -11px 10px -10px #EEE;
}
.transition-color {
  transition: background-color .3 linear;
}
.retired-member > td {
  @apply text-gray-400;
}
</style>
